   144→    // Don't wait for daemon to start - let it happen in background
   145→  } catch {
   146→    // Errors during auto-start are non-fatal - continue with command
   147→  }
   148→}
   149→
   150→program
   151→  .name("kspec")
   152→  .description("Kynetic Spec - Structured specification format CLI")
   153→  .version(version)
   154→  // AC: @output-format-option ac-format-json, ac-format-yaml, ac-global-scope
   155→  // Note: We use shorthands --json, --yaml, --raw as global options
   156→  // --format is NOT global because it conflicts with command-specific --format options (e.g., export)
   157→  // Commands can still use --format locally; the global behavior uses shorthands only
   158→  .option("--json", "Output in JSON format")
   159→  .option("--yaml", "Output in YAML format")
   160→  .option("--raw", "Output in raw JSON format (same as --json)")
   161→  .option("--debug-shadow", "Enable debug output for shadow operations")
   162→  .hook("preAction", async (thisCommand, actionCommand) => {
   163→    // Skip all hooks during batch dispatch — the batch handler manages modes itself
   164→    if (isBatchMode()) return;
   165→
   166→    // The actionCommand is the actual command being executed (e.g., 'export')
   167→    const executingCommandName = actionCommand.name();
   168→
   169→    // Check format options at top level
   170→    const opts = thisCommand.opts();
   171→
   172→    // AC: @output-format-option ac-conflict-error
   173→    // Detect conflicting format shorthand specifications
   174→    const formatFlags = [];
   175→    if (opts.json) formatFlags.push("--json");
   176→    if (opts.yaml) formatFlags.push("--yaml");
   177→    if (opts.raw) formatFlags.push("--raw");
   178→
   179→    if (formatFlags.length > 1) {
   180→      console.error(
   181→        chalk.red(`error: Conflicting format options: ${formatFlags.join(", ")}`)
   182→      );
   183→      console.error(chalk.gray("Use only one of: --json, --yaml, --raw"));
   184→      process.exit(EXIT_CODES.ERROR);
   185→    }
   186→
   187→    // AC: @output-format-option ac-json-shorthand, ac-raw-shorthand, ac-yaml-shorthand
   188→    // Set output format based on shorthand flags
   189→    if (opts.json || opts.raw) {
   190→      setJsonMode(true);
   191→    } else if (opts.yaml) {
   192→      setYamlMode(true);
   193→    }
   194→
   195→    if (opts.debugShadow) {
   196→      setVerboseMode(true);
   197→    }
   198→
   199→    // Auto-start daemon if configured and not running
   200→    // Skip for init, serve, and help commands
   201→    const skipCommands = ['init', 'serve', 'help', 'kspec'];
   202→
   203→    if (!skipCommands.includes(executingCommandName)) {
   204→      await maybeAutoStartDaemon();
   205→    }
   206→  });
   207→
   208→// Register command groups
   209→registerTasksCommands(program);
   210→registerTaskCommands(program);
   211→registerSetupCommand(program);
   212→registerSessionCommands(program);
   213→registerInitCommand(program);
   214→
   215→// Register item commands first, then add trait subcommands to it
   216→registerItemCommands(program);
   217→const itemCmd = program.commands.find((cmd) => cmd.name() === "item");
   218→if (itemCmd) {
   219→  registerItemTraitCommands(itemCmd);
   220→}
   221→
   222→registerTraitCommands(program);
   223→registerValidateCommand(program);
   224→registerHelpCommand(program);
   225→registerDoctorCommand(program);
   226→registerDeriveCommand(program);
   227→registerInboxCommands(program);
   228→registerTriageCommands(program);
   229→registerShadowCommands(program);
   230→registerLogCommand(program);
   231→registerSearchCommand(program);
   232→registerRefsCommand(program);
   233→registerServeCommands(program);
   234→registerRalphCommand(program);
   235→registerMetaCommands(program);
   236→registerLinkCommands(program);
   237→registerModuleCommands(program);
   238→registerPlanCommands(program);
   239→registerCloneForTestingCommand(program);
   240→registerWorkflowCommand(program);
   241→registerMergeDriverCommand(program);
   242→registerExportCommand(program);
   243→registerUtilCommands(program);
   244→registerBatchCommand(program);
   245→registerSkillCommands(program);
   246→registerAgentsCommands(program);
   247→
   248→// Handle unknown commands with suggestions
   249→program.on("command:*", (operands) => {
   250→  const unknownCommand = operands[0];
   251→
   252→  // Check for direct alias match
   253→  if (COMMAND_ALIASES[unknownCommand]) {
   254→    console.error(chalk.red(`error: unknown command '${unknownCommand}'`));
   255→    console.error(
   256→      chalk.yellow(`Did you mean: kspec ${COMMAND_ALIASES[unknownCommand]}?`),
   257→    );
   258→    process.exit(EXIT_CODES.ERROR);
   259→  }
   260→
   261→  // Get all available commands
   262→  const allCommands = getAllCommands(program);
   263→
   264→  // Find closest match
   265→  const suggestion = findClosestCommand(unknownCommand, allCommands);
   266→
   267→  if (suggestion) {
   268→    console.error(chalk.red(`error: unknown command '${unknownCommand}'`));
   269→    console.error(chalk.yellow(`Did you mean: kspec ${suggestion}?`));
   270→  } else {
   271→    console.error(chalk.red(`error: unknown command '${unknownCommand}'`));
   272→    console.error(chalk.gray(`Run 'kspec help' to see available commands`));
   273→  }
   274→
   275→  process.exit(EXIT_CODES.ERROR);
   276→});
   277→
   278→// Export program for introspection (used by help command)
   279→export { program };
   280→
   281→// Parse and execute (only when run directly)
   282→// Use realpathSync to resolve symlinks (e.g., when run via npm link)
   283→const scriptPath = realpathSync(process.argv[1]);
   284→if (import.meta.url === `file://${scriptPath}`) {
   285→  program.parse();
   286→}
   287→
